var i=`unit-integration-and-end-to-end-testing`;var n=84;var o={en:[{id:`T084-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`Unit, Integration & End-to-End Testing`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Mutation testing changes code in small controlled ways and checks whether the test suite detects those changes.`},{id:`B`,text:`Static analysis inspects source or compiled representations without executing full application behavior.`},{id:`C`,text:`These testing levels differ in boundary and realism: unit tests isolate a small behavior; integration tests exercise interacting components; E2E tests validate a full user or system journey.`},{id:`D`,text:`TDD follows a short red-green-refactor loop: write a failing test, implement the minimal behavior, then improve design without changing behavior.`}]},{id:`T084-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`Unit, Integration & End-to-End Testing`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Record debt with business impact, risk, affected modules, approximate remediation cost and triggers.`},{id:`B`,text:`Choose boundaries based on risk rather than naming conventions.`},{id:`C`,text:`Define properties such as round-trip correctness, preservation of totals or order independence where valid.`},{id:`D`,text:`Use consumer-driven contracts or shared schemas with executable verification.`}]},{id:`T084-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which practical project example best illustrates `},{t:`Unit, Integration & End-to-End Testing`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`A 300-line booking controller may contain validation, pricing and persistence. Extract coherent policies and retain a thin orchestrator, confirming the same responses and side effects.`},{id:`B`,text:`If changing a discount eligibility check from less-than to less-than-or-equal leaves all tests green, the threshold boundary is insufficiently tested.`},{id:`C`,text:`A booking service has unit tests for cancellation windows, integration tests for double-booking prevention and a Playwright scenario for staff confirmation.`},{id:`D`,text:`A financial transfer function must conserve total balances across accounts, regardless of valid random transfer sequences. Randomized concurrent sequences can expose missed invariants.`}]},{id:`T084-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`Unit, Integration & End-to-End Testing`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`Mutation tooling can be slow and noisy; equivalent mutants cannot be distinguished automatically in general.`},{id:`B`,text:`Feature files that repeat click-by-click UI steps become brittle.`},{id:`C`,text:`Shorter methods are not always clearer, and refactoring mixed with new features is hard to review.`},{id:`D`,text:`Excessive mocks can test a fictional system, while broad E2E tests are slow and flaky.`}]},{id:`T084-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`These testing levels differ in boundary and realism: unit tests isolate a small behavior; integration tests exercise interacting components; E2E tests validate a full user or system journey.`}]}]},{id:`T084-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`A passing unit test proves that the entire production request path works.`}]}]},{id:`T084-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`A label 'integration test' is meaningless if the database is still mocked.`}]}]},{id:`T084-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`Unit, Integration & End-to-End Testing`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Static analysis can prove every runtime business rule is implemented correctly.`},{id:`B`,text:`An E2E test should mock every external integration to claim full-stack coverage.`},{id:`C`,text:`These testing levels differ in boundary and realism: unit tests isolate a small behavior; integration tests exercise interacting components; E2E tests validate a full user or system journey.`},{id:`D`,text:`Choose boundaries based on risk rather than naming conventions.`}]},{id:`T084-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`Unit, Integration & End-to-End Testing`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`A booking service has unit tests for cancellation windows, integration tests for double-booking prevention and a Playwright scenario for staff confirmation.`},{id:`B`,text:`Technical debt has no carrying cost once the initial feature is released.`},{id:`C`,text:`A label 'integration test' is meaningless if the database is still mocked.`},{id:`D`,text:`A passing unit test proves that the entire production request path works.`}]},{id:`T084-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`A booking service has unit tests for cancellation windows, integration tests for double-booking prevention and a Playwright scenario for staff confirmation.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Ask an agent to run mutation testing on a pricing policy, inspect surviving boundary mutants and add targeted tests instead of blanket coverage increases.`},{id:`B`,text:`Ask an agent for one meaningful test at each layer for reservation confirmation. Explain which failures each catches and which remain uncovered.`},{id:`C`,text:`Ask an agent to turn ambiguous cancellation policy text into collaborative example tables, highlight unresolved business questions, then generate executable scenarios.`},{id:`D`,text:`Ask an agent to identify three concrete code smells and propose a series of small diffs, each with preserved behavior and regression tests.`}]},{id:`T084-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`How does your test fixture preserve realistic authorization and transaction behavior?`}]}]},{id:`T084-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`A booking service has unit tests for cancellation windows, integration tests for double-booking prevention and a Playwright scenario for staff confirmation.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`Unit, Integration & End-to-End Testing`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T084-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`A booking service has unit tests for cancellation windows, integration tests for double-booking prevention and a Playwright scenario for staff confirmation.`,b:!0},{t:` — propose three checks for `},{t:`Unit, Integration & End-to-End Testing`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T084-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`A booking service has unit tests for cancellation windows, integration tests for double-booking prevention and a Playwright scenario for staff confirmation.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T084-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`Unit, Integration & End-to-End Testing`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`A booking service has unit tests for cancellation windows, integration tests for double-booking prevention and a Playwright scenario for staff confirmation.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T084-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Unit-, інтеграційне та E2E-тестування`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Мутаційне тестування вносить невеликі контрольовані зміни до коду й перевіряє, чи виявляють їх тести.`},{id:`B`,text:`Статичний аналіз перевіряє код або проміжне представлення без повного виконання застосунку.`},{id:`C`,text:`Рівні тестування відрізняються межами й реалістичністю: unit перевіряє невелику поведінку, інтеграційний — взаємодію компонентів, E2E — повний користувацький або системний сценарій.`},{id:`D`,text:`TDD працює коротким циклом red-green-refactor: спершу тест, який падає, далі мінімальна реалізація, потім покращення дизайну без зміни поведінки.`}]},{id:`T084-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Unit-, інтеграційне та E2E-тестування`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Фіксуйте борг із бізнесовим впливом, ризиком, модулями, приблизною ціною виправлення й тригерами.`},{id:`B`,text:`Обирайте межі за ризиком, а не назвами.`},{id:`C`,text:`Визначайте властивості на кшталт round-trip, збереження суми або незалежності від порядку, якщо вона справді потрібна.`},{id:`D`,text:`Використовуйте consumer-driven контракти або спільні схеми з виконуваною перевіркою.`}]},{id:`T084-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який приклад із практичного проєкту найкраще ілюструє `},{t:`Unit-, інтеграційне та E2E-тестування`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Контролер бронювань на 300 рядків може містити валідацію, ціну й збереження. Винесіть узгоджені правила та залиште тонкий оркестратор, перевіривши незмінність відповідей і побічних ефектів.`},{id:`B`,text:`Якщо заміна умови з менше на менше-або-дорівнює для знижки не ламає тести, межовий випадок недостатньо перевірений.`},{id:`C`,text:`Сервіс бронювання має unit-тести періоду скасування, інтеграційні тести захисту від подвійного бронювання та Playwright-сценарій підтвердження співробітником.`},{id:`D`,text:`Функція переказу має зберігати сумарний баланс рахунків для довільних коректних послідовностей переказів. Випадкові конкурентні послідовності можуть показати приховані збої.`}]},{id:`T084-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Unit-, інтеграційне та E2E-тестування`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Мутаційні інструменти можуть бути повільними й шумними; еквівалентні мутанти не завжди можливо автоматично відрізнити.`},{id:`B`,text:`Feature-файли з кроками кожного кліку крихкі.`},{id:`C`,text:`Коротші методи не завжди ясніші, а рефакторинг разом із новими фічами важко перевіряти.`},{id:`D`,text:`Надмірні mocks тестують вигадану систему, а широкі E2E повільні й нестабільні.`}]},{id:`T084-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Рівні тестування відрізняються межами й реалістичністю: unit перевіряє невелику поведінку, інтеграційний — взаємодію компонентів, E2E — повний користувацький або системний сценарій.`}]}]},{id:`T084-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`Успішний unit-тест доводить, що весь продакшн-шлях запиту працює.`}]}]},{id:`T084-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Назва «integration test» нічого не означає, якщо БД досі підмінена.`}]}]},{id:`T084-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Unit-, інтеграційне та E2E-тестування`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Статичний аналіз доводить коректність усіх бізнес-правил під час виконання.`},{id:`B`,text:`E2E-тест має замокати всі інтеграції, щоб заявляти повне покриття.`},{id:`C`,text:`Рівні тестування відрізняються межами й реалістичністю: unit перевіряє невелику поведінку, інтеграційний — взаємодію компонентів, E2E — повний користувацький або системний сценарій.`},{id:`D`,text:`Обирайте межі за ризиком, а не назвами.`}]},{id:`T084-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Unit-, інтеграційне та E2E-тестування`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Сервіс бронювання має unit-тести періоду скасування, інтеграційні тести захисту від подвійного бронювання та Playwright-сценарій підтвердження співробітником.`},{id:`B`,text:`Технічний борг не має подальшої вартості після релізу функції.`},{id:`C`,text:`Назва «integration test» нічого не означає, якщо БД досі підмінена.`},{id:`D`,text:`Успішний unit-тест доводить, що весь продакшн-шлях запиту працює.`}]},{id:`T084-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Сервіс бронювання має unit-тести періоду скасування, інтеграційні тести захисту від подвійного бронювання та Playwright-сценарій підтвердження співробітником.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента запустити mutation testing правил цін, розібрати мутанти на межах і додати цільові тести замість формального збільшення coverage.`},{id:`B`,text:`Попросіть агента зробити по одному змістовному тесту кожного рівня для підтвердження бронювання. Поясніть, які збої вони ловлять, а які ні.`},{id:`C`,text:`Попросіть агента перетворити нечітку політику скасування на таблиці прикладів, виділити нез’ясовані бізнес-питання й створити виконувані сценарії.`},{id:`D`,text:`Попросіть агента знайти три конкретні запахи й запропонувати серію малих diff зі збереженою поведінкою та регресійними тестами.`}]},{id:`T084-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Як фікстура відтворює реалістичну авторизацію та транзакції?`}]}]},{id:`T084-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Сервіс бронювання має unit-тести періоду скасування, інтеграційні тести захисту від подвійного бронювання та Playwright-сценарій підтвердження співробітником.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Unit-, інтеграційне та E2E-тестування`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T084-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Сервіс бронювання має unit-тести періоду скасування, інтеграційні тести захисту від подвійного бронювання та Playwright-сценарій підтвердження співробітником.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Unit-, інтеграційне та E2E-тестування`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T084-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Сервіс бронювання має unit-тести періоду скасування, інтеграційні тести захисту від подвійного бронювання та Playwright-сценарій підтвердження співробітником.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T084-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Unit-, інтеграційне та E2E-тестування`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Сервіс бронювання має unit-тести періоду скасування, інтеграційні тести захисту від подвійного бронювання та Playwright-сценарій підтвердження співробітником.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var s={slug:i,topicId:84,questions:o};export{s as default,o as questions,i as slug,n as topicId};